// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address depositor, uint8 flag) public {
        amount1 = bound(amount1, 0, type(uint256).max / 2);
        amount2 = bound(amount2, 0, type(uint256).max / 2);

        vm.assume(depositor != address(0) && depositor != address(this) && depositor != address(c));

        uint256 initialTotalBalance = 0;
        uint256 initialContractBalance = address(c).balance;

        vm.deal(depositor, amount1);
        vm.prank(depositor);
        c.addToBalance{value: amount1}();
        uint256 totalAfterFirst = c.getBalance(depositor);

        vm.deal(depositor, amount2);
        vm.prank(depositor);
        c.addToBalance{value: amount2}();

        uint256 expectedTotal = amount1 + amount2;
        uint256 actualTotal = c.getBalance(depositor);

        assertTrue(actualTotal == expectedTotal);
    }
}
